fun append(ch: FileChannel, rec: ByteBuffer, at: Long): Long {
    var pos = at
    while (rec.hasRemaining()) pos += ch.write(rec, pos)   // positional writes until it is all out
    ch.force(false)                                       // fdatasync: only now may the caller reply OK
    return pos
}

